import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Events","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/item/events.md","filePath":"en/modules/item/events.md","lastUpdated":0}`),a={name:`en/modules/item/events.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to “Events”">​</a></h1><p>Item currently has five public events; the source contains no <code>ItemUpdateEvent</code> or <code>EquipmentSkillTriggerEvent</code>. The event package is <code>emaki.jiuwu.craft.item.api.event</code>.</p><table tabindex="0"><thead><tr><th>Event</th><th>Timing</th><th>Thread</th><th>Cancellable</th><th>Mutable field</th><th>Cancellation/effect</th><th>Runtime path</th></tr></thead><tbody><tr><td><code>EmakiItemCreateEvent</code></td><td>After the factory has built the stack, before it returns to the caller</td><td>global-region owner thread</td><td>Yes</td><td><code>result</code>, which must be non-null</td><td>Cancellation discards the result; public <code>create</code> returns <code>CANCELLED</code></td><td>Creation paths that enter <code>EmakiItemFactory</code> and currently own the global region</td></tr><tr><td><code>ItemRepairEvent</code></td><td>After repair validation, before charging and restoring durability</td><td>player owner thread</td><td>Yes</td><td><code>restoreAmount</code></td><td>Cancellation prevents both charging and repair; <code>&lt;= 0</code> also suppresses the repair</td><td>The material and economy repair services, including the economy path of the public <code>repair()</code></td></tr><tr><td><code>ItemSetBonusChangeEvent</code></td><td>After the active set count has actually changed</td><td>player owner thread</td><td>No</td><td>none</td><td>Post-notification, not rollbackable</td><td>Equipped set refresh, once per changed set id</td></tr><tr><td><code>ItemStateChangeEvent</code></td><td>After an item-state mutation has been committed</td><td>the owner thread that performed the mutation</td><td>No</td><td>none</td><td>Post-notification, not rollbackable</td><td>The <code>set</code>/<code>add</code>/<code>remove</code> commit paths of <code>state()</code></td></tr><tr><td><code>ItemStateThresholdEvent</code></td><td>After a numeric item-state mutation crossed a configured threshold</td><td>the owner thread that performed the mutation</td><td>No</td><td>none</td><td>Post-notification, not rollbackable</td><td>Once per crossed threshold, after the commit and the once-threshold re-arm bookkeeping</td></tr></tbody></table><p>The creation event currently has a null player. When the calling thread does not own the global region, the runtime skips the creation event and still returns the detached build result, so it is not a complete audit stream for every ItemStack creation. Migration and ordinary refresh have no dedicated public events. <code>ItemSetBonusChangeEvent</code> is a post event and cannot be cancelled.</p><p><code>ItemStateChangeEvent</code> exposes <code>getItem()</code> (a clone), <code>getMutation()</code>, <code>getHolder()</code> (null when the holder was unknown), and the <code>getKey()</code>, <code>getOldValue()</code>, <code>getNewValue()</code>, and <code>getDelta()</code> forwarded from the mutation.</p><p><code>ItemStateThresholdEvent</code> exposes <code>getItem()</code>, <code>getHolder()</code>, <code>getKey()</code>, <code>getOldValue()</code>, <code>getNewValue()</code>, <code>getThreshold()</code>, <code>getThresholdId()</code>, <code>getDirection()</code> (<code>UP</code>/<code>DOWN</code>), <code>isOnce()</code>, and <code>isRearmed()</code>. It only covers numeric fields with configured thresholds (<code>INTEGER</code>, <code>LONG</code>, <code>DOUBLE</code>); an upward crossing dispatches once per threshold in ascending order and a downward crossing in descending order. It never fires for rejected or unchanged mutations, reserved <code>meta.</code> metadata keys, <code>BOOLEAN</code> and <code>STRING</code> fields, numeric fields without configured thresholds, changes that stay on the same side of a threshold, a <code>once</code> threshold still latched, or state restored verbatim by a rebuild.</p>`,6)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};